-- Virtual access keys preserve raw JSON; full ID equality remains in every relationship join.
-- Remove the V10 hidden functional columns before adding visible virtual columns online.
ALTER TABLE scientific_candidate DROP INDEX ix_graph_native_taxon, ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE scientific_candidate ADD graph_namespace VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (LEFT(JSON_UNQUOTE(JSON_EXTRACT(normalized_payload,'$.source_namespace')),32)) VIRTUAL, ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE scientific_candidate ADD graph_native_taxon_id VARCHAR(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (LEFT(JSON_UNQUOTE(JSON_EXTRACT(normalized_payload,'$.source_taxon_id')),191)) VIRTUAL, ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE scientific_candidate ADD INDEX ix_graph_taxon_reference(source_id,pipeline,graph_namespace,graph_native_taxon_id), ALGORITHM=INPLACE, LOCK=NONE;
CREATE VIEW graph_trait_edge AS
 SELECT CONCAT('ct:',candidate_id,':',field_key,':',ordinality) AS id,
 CONCAT('candidate:',candidate_id) AS from_id,CONCAT('trait:',candidate_id,':',field_key,':',ordinality) AS to_id,
 'HAS_TRAIT' AS relation_type,'来源性状词与词表投影' AS display_label,graph_state AS verification_state,
 publication_state,source_id,locator,candidate_id,field_key,ordinality FROM graph_trait;
CREATE OR REPLACE VIEW graph_edge AS
SELECT CONCAT('sf:',s.id,':',a.id) AS id,CONCAT('source:',s.id) AS from_id,CONCAT('file:',a.id) AS to_id,'SOURCE_FILE' AS relation_type,'SHA-256 相同的注册文件' AS display_label,'HASH_MATCH' AS verification_state,'METADATA_ONLY' AS publication_state,s.id AS source_id,JSON_OBJECT('match','EXACT_SHA256') AS locator FROM scientific_source_version s JOIN source_asset a ON a.sha256=s.sha256
UNION ALL
SELECT CONCAT('pi:',p.id),CONCAT('plant:',p.id),CONCAT('taxon:',p.taxon_id),'IDENTITY_REFERENCE','目录分类身份引用','SOURCE_REPORTED',IF(p.is_public=1,'METADATA_ONLY','CANDIDATE'),p.source_id,p.locator FROM graph_catalog p WHERE p.taxon_id IS NOT NULL
UNION ALL
SELECT CONCAT('tp:',t.id),CONCAT('taxon:',t.id),CONCAT('taxon:',t.parent_id),'PARENT_TAXON','来源分类父级','SOURCE_REPORTED',IF(t.is_public=1 AND parent.is_public=1,'METADATA_ONLY','CANDIDATE'),t.source_id,t.locator FROM graph_taxon t JOIN graph_taxon parent ON parent.id=t.parent_id
UNION ALL
SELECT CONCAT('pn:',n.id),CONCAT('plant:',n.plant_id),CONCAT('pname:',n.id),'HAS_NAME','目录记录名称','SOURCE_REPORTED',IF(p.is_public=1 AND n.review_state='APPROVED','METADATA_ONLY','CANDIDATE'),p.source_id,e.locator FROM plant_name n JOIN graph_catalog p ON p.id=n.plant_id LEFT JOIN evidence e ON e.id=n.evidence_id
UNION ALL
SELECT CONCAT('tn:',n.id),CONCAT('taxon:',n.taxon_id),CONCAT('tname:',n.id),'HAS_NAME','分类单元名称','SOURCE_REPORTED',IF(t.is_public=1 AND n.review_state='APPROVED','METADATA_ONLY','CANDIDATE'),t.source_id,e.locator FROM taxon_name n JOIN graph_taxon t ON t.id=n.taxon_id LEFT JOIN evidence e ON e.id=n.evidence_id
UNION ALL
SELECT CONCAT('ts:',t.id),CONCAT('taxon:',t.id),CONCAT('source:',t.source_id),'SOURCED_FROM','分类原始证据','SOURCE_REPORTED',IF(t.is_public=1,'METADATA_ONLY','CANDIDATE'),t.source_id,t.locator FROM graph_taxon t WHERE t.source_id IS NOT NULL
UNION ALL
SELECT CONCAT('cs:',c.id),CONCAT('candidate:',c.id),CONCAT('source:',c.source_id),'SOURCED_FROM','观测直接来源',c.graph_state,c.publication_state,c.source_id,c.locator FROM graph_candidate c
UNION ALL
SELECT CONCAT('sm:',o.candidate_id),CONCAT('sample:',o.sample_id),CONCAT('candidate:',o.candidate_id),'HAS_MEASUREMENT','独立样本观测',c.graph_state,c.publication_state,c.source_id,c.locator FROM scientific_lipid_observation o JOIN graph_candidate c ON c.id=o.candidate_id AND c.source_id=o.source_id JOIN scientific_sample sm ON sm.id=o.sample_id WHERE JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.study_id'))=sm.study_key AND JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.sample_id'))=sm.sample_key
UNION ALL
SELECT CONCAT('ss:',s.id),CONCAT('sample:',s.id),CONCAT('source:',s.source_id),'SOURCED_FROM','样本登记来源','SOURCE_REPORTED',IF(EXISTS(SELECT 1 FROM scientific_lipid_observation o JOIN published_scientific_fact f ON f.id=o.candidate_id WHERE o.sample_id=s.id),'PUBLISHED','CANDIDATE'),s.source_id,JSON_OBJECT('study_id',s.study_key,'sample_id',s.sample_key) FROM scientific_sample s
UNION ALL
SELECT CONCAT('doc:',l.id),CONCAT('candidate:',l.candidate_id),CONCAT('source:',l.document_source_id),'SUPPORTED_BY','明确关联原文献',c.graph_state,c.publication_state,l.document_source_id,l.locator FROM scientific_evidence_link l JOIN graph_candidate c ON c.id=l.candidate_id
UNION ALL
SELECT CONCAT('ct:',candidate_id,':',field_key,':',ordinality),CONCAT('candidate:',candidate_id),CONCAT('trait:',candidate_id,':',field_key,':',ordinality),'HAS_TRAIT','来源性状词与词表投影',graph_state,publication_state,source_id,locator FROM graph_trait
UNION ALL
SELECT CONCAT('accepted_taxon_id:',c.id,':',t.id),CONCAT('candidate:',c.id),CONCAT('candidate:',t.id),'ACCEPTED_TAXON','同来源版本原生分类 ID 引用',c.graph_state,IF(c.publication_state='PUBLISHED' AND IF(EXISTS(SELECT 1 FROM published_scientific_fact target_fact WHERE target_fact.id=t.id),'PUBLISHED','CANDIDATE')='PUBLISHED','PUBLISHED','CANDIDATE'),c.source_id,c.locator FROM graph_candidate c JOIN scientific_candidate t FORCE INDEX (ix_graph_taxon_reference) ON t.source_id=c.source_id AND t.pipeline='TAXONOMY' AND t.graph_namespace=LEFT(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace')),32) AND t.graph_native_taxon_id=LEFT(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.accepted_taxon_id')),191) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(t.normalized_payload,'$.source_taxon_id')) AS CHAR(191)) COLLATE utf8mb4_bin)=(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.accepted_taxon_id')) AS CHAR(191)) COLLATE utf8mb4_bin) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(t.normalized_payload,'$.source_namespace')) AS CHAR(32)) COLLATE utf8mb4_bin)=(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace')) AS CHAR(32)) COLLATE utf8mb4_bin) WHERE c.pipeline='TAXONOMY' AND JSON_TYPE(JSON_EXTRACT(c.normalized_payload,'$.accepted_taxon_id'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.accepted_taxon_id'))<>'' AND JSON_TYPE(JSON_EXTRACT(t.normalized_payload,'$.source_taxon_id'))='STRING' AND JSON_TYPE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace'))='STRING'
UNION ALL
SELECT CONCAT('parent_taxon_id:',c.id,':',t.id),CONCAT('candidate:',c.id),CONCAT('candidate:',t.id),'PARENT_TAXON','同来源版本原生分类 ID 引用',c.graph_state,IF(c.publication_state='PUBLISHED' AND IF(EXISTS(SELECT 1 FROM published_scientific_fact target_fact WHERE target_fact.id=t.id),'PUBLISHED','CANDIDATE')='PUBLISHED','PUBLISHED','CANDIDATE'),c.source_id,c.locator FROM graph_candidate c JOIN scientific_candidate t FORCE INDEX (ix_graph_taxon_reference) ON t.source_id=c.source_id AND t.pipeline='TAXONOMY' AND t.graph_namespace=LEFT(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace')),32) AND t.graph_native_taxon_id=LEFT(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.parent_taxon_id')),191) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(t.normalized_payload,'$.source_taxon_id')) AS CHAR(191)) COLLATE utf8mb4_bin)=(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.parent_taxon_id')) AS CHAR(191)) COLLATE utf8mb4_bin) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(t.normalized_payload,'$.source_namespace')) AS CHAR(32)) COLLATE utf8mb4_bin)=(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace')) AS CHAR(32)) COLLATE utf8mb4_bin) WHERE c.pipeline='TAXONOMY' AND JSON_TYPE(JSON_EXTRACT(c.normalized_payload,'$.parent_taxon_id'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.parent_taxon_id'))<>'' AND JSON_TYPE(JSON_EXTRACT(t.normalized_payload,'$.source_taxon_id'))='STRING' AND JSON_TYPE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace'))='STRING';
CREATE OR REPLACE VIEW graph_public_edge AS
SELECT CONCAT('sf:',s.id,':',a.id) AS id,CONCAT('source:',s.id) AS from_id,CONCAT('file:',a.id) AS to_id,'SOURCE_FILE' AS relation_type,'SHA-256 相同的注册文件' AS display_label,'HASH_MATCH' AS verification_state,'METADATA_ONLY' AS publication_state,s.id AS source_id,JSON_OBJECT('match','EXACT_SHA256') AS locator FROM scientific_source_version s JOIN source_asset a ON a.sha256=s.sha256
UNION ALL
SELECT CONCAT('pi:',p.id),CONCAT('plant:',p.id),CONCAT('taxon:',p.taxon_id),'IDENTITY_REFERENCE','目录分类身份引用','SOURCE_REPORTED',IF(p.is_public=1,'METADATA_ONLY','CANDIDATE'),p.source_id,p.locator FROM graph_catalog p WHERE p.taxon_id IS NOT NULL AND p.is_public=1
UNION ALL
SELECT CONCAT('tp:',t.id),CONCAT('taxon:',t.id),CONCAT('taxon:',t.parent_id),'PARENT_TAXON','来源分类父级','SOURCE_REPORTED',IF(t.is_public=1 AND parent.is_public=1,'METADATA_ONLY','CANDIDATE'),t.source_id,t.locator FROM graph_taxon t JOIN graph_taxon parent ON parent.id=t.parent_id WHERE t.is_public=1 AND parent.is_public=1
UNION ALL
SELECT CONCAT('pn:',n.id),CONCAT('plant:',n.plant_id),CONCAT('pname:',n.id),'HAS_NAME','目录记录名称','SOURCE_REPORTED',IF(p.is_public=1 AND n.review_state='APPROVED','METADATA_ONLY','CANDIDATE'),p.source_id,e.locator FROM plant_name n JOIN graph_catalog p ON p.id=n.plant_id LEFT JOIN evidence e ON e.id=n.evidence_id WHERE p.is_public=1 AND n.review_state='APPROVED'
UNION ALL
SELECT CONCAT('tn:',n.id),CONCAT('taxon:',n.taxon_id),CONCAT('tname:',n.id),'HAS_NAME','分类单元名称','SOURCE_REPORTED',IF(t.is_public=1 AND n.review_state='APPROVED','METADATA_ONLY','CANDIDATE'),t.source_id,e.locator FROM taxon_name n JOIN graph_taxon t ON t.id=n.taxon_id LEFT JOIN evidence e ON e.id=n.evidence_id WHERE t.is_public=1 AND n.review_state='APPROVED'
UNION ALL
SELECT CONCAT('ts:',t.id),CONCAT('taxon:',t.id),CONCAT('source:',t.source_id),'SOURCED_FROM','分类原始证据','SOURCE_REPORTED',IF(t.is_public=1,'METADATA_ONLY','CANDIDATE'),t.source_id,t.locator FROM graph_taxon t WHERE t.source_id IS NOT NULL AND t.is_public=1
UNION ALL
SELECT CONCAT('cs:',c.id),CONCAT('candidate:',c.id),CONCAT('source:',c.source_id),'SOURCED_FROM','观测直接来源',c.graph_state,c.publication_state,c.source_id,c.locator FROM graph_candidate c WHERE c.id IN(SELECT id FROM published_scientific_fact)
UNION ALL
SELECT CONCAT('sm:',o.candidate_id),CONCAT('sample:',o.sample_id),CONCAT('candidate:',o.candidate_id),'HAS_MEASUREMENT','独立样本观测',c.graph_state,c.publication_state,c.source_id,c.locator FROM scientific_lipid_observation o JOIN graph_candidate c ON c.id=o.candidate_id AND c.source_id=o.source_id JOIN scientific_sample sm ON sm.id=o.sample_id WHERE JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.study_id'))=sm.study_key AND JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.sample_id'))=sm.sample_key AND c.id IN(SELECT id FROM published_scientific_fact)
UNION ALL
SELECT CONCAT('ss:',s.id),CONCAT('sample:',s.id),CONCAT('source:',s.source_id),'SOURCED_FROM','样本登记来源','SOURCE_REPORTED',IF(EXISTS(SELECT 1 FROM scientific_lipid_observation o JOIN published_scientific_fact f ON f.id=o.candidate_id WHERE o.sample_id=s.id),'PUBLISHED','CANDIDATE'),s.source_id,JSON_OBJECT('study_id',s.study_key,'sample_id',s.sample_key) FROM scientific_sample s WHERE s.id IN(SELECT o.sample_id FROM scientific_lipid_observation o JOIN published_scientific_fact f ON f.id=o.candidate_id)
UNION ALL
SELECT CONCAT('doc:',l.id),CONCAT('candidate:',l.candidate_id),CONCAT('source:',l.document_source_id),'SUPPORTED_BY','明确关联原文献',c.graph_state,c.publication_state,l.document_source_id,l.locator FROM scientific_evidence_link l JOIN graph_candidate c ON c.id=l.candidate_id WHERE c.id IN(SELECT id FROM published_scientific_fact)
UNION ALL
SELECT CONCAT('ct:',candidate_id,':',field_key,':',ordinality),CONCAT('candidate:',candidate_id),CONCAT('trait:',candidate_id,':',field_key,':',ordinality),'HAS_TRAIT','来源性状词与词表投影',graph_state,publication_state,source_id,locator FROM graph_trait WHERE candidate_id IN(SELECT id FROM published_scientific_fact)
UNION ALL
SELECT CONCAT('accepted_taxon_id:',c.id,':',t.id),CONCAT('candidate:',c.id),CONCAT('candidate:',t.id),'ACCEPTED_TAXON','同来源版本原生分类 ID 引用',c.graph_state,IF(c.publication_state='PUBLISHED' AND IF(EXISTS(SELECT 1 FROM published_scientific_fact target_fact WHERE target_fact.id=t.id),'PUBLISHED','CANDIDATE')='PUBLISHED','PUBLISHED','CANDIDATE'),c.source_id,c.locator FROM graph_candidate c JOIN scientific_candidate t FORCE INDEX (ix_graph_taxon_reference) ON t.source_id=c.source_id AND t.pipeline='TAXONOMY' AND t.graph_namespace=LEFT(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace')),32) AND t.graph_native_taxon_id=LEFT(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.accepted_taxon_id')),191) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(t.normalized_payload,'$.source_taxon_id')) AS CHAR(191)) COLLATE utf8mb4_bin)=(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.accepted_taxon_id')) AS CHAR(191)) COLLATE utf8mb4_bin) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(t.normalized_payload,'$.source_namespace')) AS CHAR(32)) COLLATE utf8mb4_bin)=(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace')) AS CHAR(32)) COLLATE utf8mb4_bin) WHERE c.pipeline='TAXONOMY' AND JSON_TYPE(JSON_EXTRACT(c.normalized_payload,'$.accepted_taxon_id'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.accepted_taxon_id'))<>'' AND JSON_TYPE(JSON_EXTRACT(t.normalized_payload,'$.source_taxon_id'))='STRING' AND JSON_TYPE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace'))='STRING' AND c.id IN(SELECT id FROM published_scientific_fact) AND t.id IN(SELECT id FROM published_scientific_fact)
UNION ALL
SELECT CONCAT('parent_taxon_id:',c.id,':',t.id),CONCAT('candidate:',c.id),CONCAT('candidate:',t.id),'PARENT_TAXON','同来源版本原生分类 ID 引用',c.graph_state,IF(c.publication_state='PUBLISHED' AND IF(EXISTS(SELECT 1 FROM published_scientific_fact target_fact WHERE target_fact.id=t.id),'PUBLISHED','CANDIDATE')='PUBLISHED','PUBLISHED','CANDIDATE'),c.source_id,c.locator FROM graph_candidate c JOIN scientific_candidate t FORCE INDEX (ix_graph_taxon_reference) ON t.source_id=c.source_id AND t.pipeline='TAXONOMY' AND t.graph_namespace=LEFT(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace')),32) AND t.graph_native_taxon_id=LEFT(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.parent_taxon_id')),191) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(t.normalized_payload,'$.source_taxon_id')) AS CHAR(191)) COLLATE utf8mb4_bin)=(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.parent_taxon_id')) AS CHAR(191)) COLLATE utf8mb4_bin) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(t.normalized_payload,'$.source_namespace')) AS CHAR(32)) COLLATE utf8mb4_bin)=(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace')) AS CHAR(32)) COLLATE utf8mb4_bin) WHERE c.pipeline='TAXONOMY' AND JSON_TYPE(JSON_EXTRACT(c.normalized_payload,'$.parent_taxon_id'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.parent_taxon_id'))<>'' AND JSON_TYPE(JSON_EXTRACT(t.normalized_payload,'$.source_taxon_id'))='STRING' AND JSON_TYPE(JSON_EXTRACT(c.normalized_payload,'$.source_namespace'))='STRING' AND c.id IN(SELECT id FROM published_scientific_fact) AND t.id IN(SELECT id FROM published_scientific_fact);
